const dotSize = 20;
let colors;
let dots;

function setup() {
  createCanvas(500, 500);
  noStroke();

  initDots();

  let pal = shuffle(["#fff247", "#47e9ff", "#8447ff", "#ff47ce"]);
  colors = [
    [pal[0], pal[1], pal[2], pal[3]],
    [pal[0], pal[2], pal[3], pal[1]],
    [pal[3], pal[2], pal[1], pal[0]],
    [pal[2], pal[0], pal[1], pal[3]]
  ];
}

function draw() {
  background("#0e0e10");

  for (let dot of dots) {
    dot.draw();
  }
}

function initDots() {
  dots = [];

  let countLines = 0;
  let xSep = dotSize;
  let ySep = xSep * sqrt(3)/2;
  let x = 0;
  let y = -dotSize/2;
  let _wG_1 = 0; while ((y < height + dotSize) && ++_wG_1 < 20000) {
    if (countLines++ % 2 === 0) {
      x = -xSep / 2;
    } else {
      x = 0;
    }
    let id = floor(countLines/2) % 2;
    let _wG_2 = 0; while ((x < width + dotSize) && ++_wG_2 < 20000) {
      dots.push(new Dot(x, y, ((id++)%2)*2 + countLines%2));
      x += xSep;
    }
    y += ySep;
  }
}

function Dot(x_, y_, id_) {
  this.x = x_;
  this.y = y_;
  this.id = id_; // determines the color and whether this dot becomes big, or disppears
  this.distToCentre = (this.x*width/2 + this.y*height/2)/100;

  this.draw = function() {
    let t = frameCount/100+this.y/800;
    //let t = abs(frameCount/100-this.distToCentre/800);
    let z = t%1;
    if (z > 0.5) z = 1-z; // z goes up then down
    z = sq(z*2); // *2 because we want z to go up to 1, squared because it make it look nicer
    let size = (this.id == floor(t%4)) ? dotSize * (1+z) : dotSize * (1-z);
    let palette = floor((t+0.5)%4);
    fill(colors[palette][this.id]);
    //size+=2
    beginShape();
    for (let theta = PI/6; theta < TWO_PI; theta += (Math.max(0.001, Math.abs(PI/3)) || 1)) {
      vertex(this.x+size/2*cos(theta), this.y+size/2*sin(theta));
    }
    endShape();
  }
}
